{
  "name": "伪时钟时序调度组件",
  "name_en": "Pseudoclock Timing Scheduler",
  "manufacturer": "",
  "description": "用于实验时序编排的非物理软件组件。它负责汇总各时钟线输出的变化时刻，展开伪时钟节拍，处理触发与停止时间约束，并生成供下游实验设备使用的时序数据与代码。",
  "description_en": "A non-physical software component for experiment timing orchestration. It collects output change times across clock lines, expands pseudoclock ticks, handles trigger and stop-time constraints, and generates timing data and code for downstream lab devices.",
  "actions": [
    {
      "action_name": "auto-add_device",
      "description": "添加由该伪时钟管理的子设备。",
      "description_en": "Add a child device managed by this pseudoclock."
    },
    {
      "action_name": "auto-collect_change_times",
      "description": "收集各输出及各时钟线的变化时刻。",
      "description_en": "Collect change times from outputs and clock lines."
    },
    {
      "action_name": "auto-expand_change_times",
      "description": "将变化时刻区间展开为具体的时钟节拍序列。",
      "description_en": "Expand change-time intervals into concrete clock tick sequences."
    },
    {
      "action_name": "auto-generate_clock",
      "description": "生成伪时钟节拍表及对应输出时序。",
      "description_en": "Generate the pseudoclock tick schedule and corresponding output timing."
    },
    {
      "action_name": "auto-generate_code",
      "description": "生成并写出伪时钟时序代码或指令数据。",
      "description_en": "Generate and write pseudoclock timing code or instruction data."
    },
    {
      "action_name": "auto-get_outputs_by_clockline",
      "description": "获取按时钟线分组的输出。",
      "description_en": "Get outputs grouped by clock line."
    },
    {
      "action_name": "auto-minimum_clock_high_time",
      "description": "获取最小时钟高电平时间。",
      "description_en": "Get the minimum clock high time."
    },
    {
      "action_name": "auto-clock_limit",
      "description": "获取时钟速率限制。",
      "description_en": "Get the clock rate limit."
    },
    {
      "action_name": "auto-trigger",
      "description": "处理或发出该伪时钟设备的触发事件。",
      "description_en": "Handle or issue the trigger event for this pseudoclock device."
    },
    {
      "action_name": "auto-do_checks",
      "description": "执行时序与配置一致性检查。",
      "description_en": "Run timing and configuration consistency checks."
    },
    {
      "action_name": "auto-is_master_pseudoclock",
      "description": "获取是否为主伪时钟。",
      "description_en": "Get whether this is the master pseudoclock."
    },
    {
      "action_name": "auto-set_initial_trigger_time",
      "description": "设置初始触发时间。",
      "description_en": "Set the initial trigger time."
    },
    {
      "action_name": "auto-offset_instructions_from_trigger",
      "description": "按触发时间偏移指令时序。",
      "description_en": "Offset instruction timing relative to the trigger time."
    }
  ],
  "tag_hints": [
    "pseudoclock timing",
    "experiment sequencing",
    "clock line scheduling",
    "trigger timing",
    "instruction generation",
    "labscript timing core"
  ]
}

